/**
 * Campaign workflows historically created registered Git worktrees directly
 * under Smithers' hidden worktree roots, before the engine added owner files.
 * Surface only those exact locations; arbitrary human worktrees stay invisible.
 *
 * @param {string} rootDir
 */
declare function listUnownedCampaignWorktrees(rootDir: string): Promise<{
    exists: boolean;
    updatedAtMs: number;
    vcsType: string;
    path: string;
    head?: string | null | undefined;
    branch?: string | null | undefined;
    locked?: boolean | undefined;
    prunable?: boolean | undefined;
}[]>;
/**
 * Reclaim legacy campaign worktrees only after explicit opt-in. Unlike the
 * owned-worktree `force` path, this never discards unpublished changes: an
 * unowned lane must be clean and its HEAD must already exist upstream.
 *
 * @param {{
 *   rootDir: string;
 *   includeUnmanaged?: boolean;
 *   olderThanMs?: number;
 *   nowMs?: number;
 *   dryRun?: boolean;
 *   liveCwds?: string[] | null;
 *   sizeOf?: (path: string) => Promise<number>;
 * }} options
 */
declare function reapUnownedCampaignWorktrees(options: {
    rootDir: string;
    includeUnmanaged?: boolean;
    olderThanMs?: number;
    nowMs?: number;
    dryRun?: boolean;
    liveCwds?: string[] | null;
    sizeOf?: (path: string) => Promise<number>;
}): Promise<{
    removed: {
        path: string;
        branch: string | null | undefined;
        head: string | null | undefined;
        bytes: any;
    }[];
    skipped: {
        reason: string;
        path: string;
        branch: string | null | undefined;
        head: string | null | undefined;
        bytes: any;
    }[];
    bytesFreed: number;
    totalBytes: number;
    dryRun: boolean;
    includeUnmanaged: boolean;
}>;

export { listUnownedCampaignWorktrees, reapUnownedCampaignWorktrees };
